      out.write("    	rowData += \"<button type='button' class='btn btn-sm btn-danger' onclick='doDelete(\" + course.course_id + \", event)'>Delete</button>\";\r\n");
      out.write("    	rowData += \"</td>\";\r\n");
      out.write("    	rowData +=\"</tr>\";\r\n");
      out.write("    	return rowData;\r\n");
      out.write("    }\r\n");
      out.write("    \r\n");
      out.write("    function editCourse(course_id){\r\n");
      out.write("    	$('#addCourseModalLabel').text('Edit Course');\r\n");
      out.write("    	$('#submitButton').text('Update Course');\r\n");
      out.write("    	\r\n");
      out.write("    	$.ajax({\r\n");
