      out.write("    			console.log(data);\r\n");
      out.write("    			var course = eval(data);\r\n");
      out.write("    			if(course){\r\n");
      out.write("    				$(\"#actionID\").val('update');\r\n");
      out.write("    				$('#course_id').val(course.course_id);\r\n");
      out.write("    				$('#courseName').val(course.course_name);\r\n");
      out.write("    				$('#courseDuration').val(course.course_duration)\r\n");
      out.write("    				$('#addbtnID').text('Update');\r\n");
      out.write("    				$('#addCourseModal').modal('show');\r\n");
      out.write("    			}else{\r\n");
      out.write("    				alert('Failed to load teacher data.');\r\n");
      out.write("    			}\r\n");
      out.write("    		},\r\n");
      out.write("    		\r\n");
      out.write("    		error: function(){\r\n");
      out.write("    			alert('Error fetching course data.');\r\n");
      out.write("    		}\r\n");
      out.write("    	});\r\n");
      out.write("    }\r\n");
      out.write("    \r\n");
